{{(() => {
  const ratings = [
    Rating29Copy.value,
		Rating30Copy.value,
		Rating31Copy.value,
		Rating32Copy.value,
    Rating33Copy.value,
		Rating34Copy.value,
		Rating35Copy.value,
		Rating36Copy.value
  ];

  const hasInvalidRating = ratings.some(r => r === null || r === 0);

  if (hasInvalidRating) {
    return "OBIETTIVO DELLA SETTIMANA: CAPACITÀ DI LAVORARE CON COLLEGHE E INTRODUZIONE AL COMPRO ORO";
  }

  const somma = ratings.reduce((acc, val) => acc + val, 0);

  return somma === 0 ? "" : (somma >= 18 ? "OBIETTIVO DELLA SETTIMANA RAGGIUNTO: CAPACITÀ DI LAVORARE CON COLLEGHE E INTRODUZIONE AL COMPRO ORO" : "OBIETTIVO DELLA SETTIMANA NON RAGGIUNTO: CAPACITÀ DI LAVORARE CON COLLEGHE E INTRODUZIONE AL COMPRO ORO");
})()
}}

